const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS="*{box-sizing:border-box}\n.pg{width:100%;height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px;padding:10px;background:var(--paper);color:var(--ink);border-radius:16px;font-size:13px;line-height:1.25;overflow:hidden}\nbutton{font:inherit;color:inherit;background:none;border:0;padding:0;margin:0;cursor:pointer;text-align:inherit}\nbutton:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.bar{display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0;flex:none}\n.ttl{display:flex;flex-direction:column;min-width:0;gap:1px}\n.name{font-weight:700;font-size:15px;white-space:nowrap}\n.range{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.rg-a{margin-right:4px}\n.ctl{display:flex;gap:4px;flex:none}\n.ib{width:26px;height:26px;border-radius:8px;background:var(--button-paper);border:1px solid var(--line);display:grid;place-items:center;font-size:16px;line-height:1;text-align:center;color:var(--ink)}\n.ib:disabled{opacity:.35;cursor:default}\n.ib.add{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:700}\n.sum{display:none;align-items:center;gap:6px;flex:none;font-size:12px;color:var(--muted)}\n.sum span:first-child{color:var(--ink);font-weight:600}\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:6px;scrollbar-width:thin}\n.wk{position:sticky;top:0;z-index:2;background:var(--paper);display:grid;grid-template-columns:minmax(0,1fr);padding:0 0 2px;flex:none}\n.wk-sp{display:none}\n.wds,.cells{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px;min-width:0}\n.wd{display:flex;flex-direction:column;align-items:center;font-size:10px;color:var(--muted);line-height:1.1}\n.wd .w{font-weight:600}\n.wd .dt{display:none;font-size:10px}\n.wd.today{color:var(--ink);font-weight:700}\n.wd.today .w{text-decoration:underline;text-decoration-color:var(--accent);text-decoration-thickness:2px;text-underline-offset:2px}\n.habit{display:grid;grid-template-columns:minmax(0,1fr);grid-template-areas:\"hd\" \"cells\" \"meta\";row-gap:3px;min-width:0;flex:none}\n.hd{grid-area:hd;display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0}\n.cells{grid-area:cells;align-self:center}\n.meta{grid-area:meta;display:none}\n.hname{display:flex;align-items:center;gap:4px;min-width:0;flex:1;font-weight:600;font-size:12px}\n.nm{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pen{color:var(--muted);font-size:11px;flex:none}\n.stat{display:flex;align-items:center;gap:4px;flex:none;font-size:11px;color:var(--muted)}\n.stat .n{font-variant-numeric:tabular-nums;font-weight:600;color:var(--ink)}\n.ok{background:var(--soft);color:var(--ink);border-radius:999px;padding:0 6px;font-size:10px;font-weight:600;white-space:nowrap}\n.cell{aspect-ratio:1;min-width:0;border-radius:6px;border:1px dashed var(--muted);background:var(--button-paper);display:grid;place-items:center;font-size:12px;font-weight:700;color:var(--on-accent);line-height:1;text-align:center}\n.cell.on{background:var(--accent);border:1px solid var(--accent)}\n.cell.today{border:2px solid var(--accent-alt)}\n.ticks{display:flex;gap:2px}\n.tick{flex:1;max-width:14px;height:5px;border-radius:3px;background:var(--soft);box-shadow:inset 0 0 0 1px var(--line)}\n.tick.f{background:var(--accent);box-shadow:none}\n.tot{font-size:10px;color:var(--muted)}\n.empty{padding:16px 8px;text-align:center;color:var(--muted);font-size:12px}\n.hint{display:none;font-size:11px;color:var(--muted);flex:none}\n.err{flex:none;font-size:12px;padding:4px 8px;border-radius:8px;background:var(--soft);color:var(--ink);border:1px solid var(--line)}\n.back{font-size:12px;font-weight:600;padding:4px 8px 4px 4px;border-radius:8px;color:var(--ink);min-height:26px}\n.etitle{font-weight:700;font-size:13px}\n.ebody{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.fields{display:flex;flex-direction:column;gap:6px}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.lb{font-size:11px;color:var(--muted);font-weight:600}\n.inp{width:100%;height:30px;border-radius:8px;border:1px solid var(--line);background:var(--button-paper);color:var(--ink);padding:0 8px;font:inherit;font-size:13px}\n.inp::placeholder{color:var(--muted)}\n.segs{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px}\n.sgb{height:26px;border-radius:7px;border:1px solid var(--line);background:var(--button-paper);color:var(--ink);text-align:center;font-weight:600;font-size:12px}\n.sgb.sel{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}\n.note{font-size:11px;color:var(--muted)}\n.row{display:flex;gap:6px;flex:none}\n.btn{flex:1;min-width:0;height:30px;border-radius:9px;border:1px solid var(--line);background:var(--button-paper);color:var(--ink);text-align:center;font-weight:600;font-size:12px;padding:0 6px;white-space:nowrap}\n.btn.primary{flex:1.4;background:var(--accent);color:var(--on-accent);border-color:transparent}\n.btn.ghost{flex:.8}\n.btn:disabled{opacity:.5;cursor:default}\n.confirm{display:flex;flex-direction:column;gap:6px;flex:none}\n.cmsg{font-size:11px;color:var(--ink)}\n\n/* 3x3 */\n.card[data-size=\"3x3\"] .pg{padding:8px;gap:4px}\n.card[data-size=\"3x3\"] .name{display:none}\n.card[data-size=\"3x3\"] .range{font-size:12px;font-weight:700;color:var(--ink)}\n.card[data-size=\"3x3\"] .range.now .rg-b,.card[data-size=\"3x3\"] .range.past .rg-a{display:none}\n.card[data-size=\"3x3\"] .ib{width:24px;height:24px}\n.card[data-size=\"3x3\"] .list{gap:4px}\n.card[data-size=\"3x3\"] .habit{row-gap:2px}\n.card[data-size=\"3x3\"] .wd .w{font-size:10px}\n\n/* 3x6 */\n.card[data-size=\"3x6\"] .pg{padding:12px 10px;gap:8px}\n.card[data-size=\"3x6\"] .rg-a{display:none}\n.card[data-size=\"3x6\"] .sum{display:flex}\n.card[data-size=\"3x6\"] .hint{display:block}\n.card[data-size=\"3x6\"] .meta{display:block}\n.card[data-size=\"3x6\"] .wd .dt{display:block}\n.card[data-size=\"3x6\"] .list{gap:8px}\n.card[data-size=\"3x6\"] .habit{padding-bottom:8px;border-bottom:1px solid var(--line);row-gap:5px}\n.card[data-size=\"3x6\"] .habit:last-child{border-bottom:0}\n.card[data-size=\"3x6\"] .hname{font-size:13px}\n.card[data-size=\"3x6\"] .inp{height:34px}\n.card[data-size=\"3x6\"] .sgb{height:30px}\n.card[data-size=\"3x6\"] .btn{height:34px}\n\n/* wide: 6x3 and 6x6 */\n.card[data-size^=\"6x\"] .pg{--px:8px;--py:4px;--hw:112px}\n.card[data-size^=\"6x\"] .wk,.card[data-size^=\"6x\"] .habit{grid-template-columns:var(--hw) minmax(0,1fr);column-gap:10px}\n.card[data-size^=\"6x\"] .wk{padding:0 calc(var(--px) + 1px) 2px}\n.card[data-size^=\"6x\"] .wk-sp{display:block}\n.card[data-size^=\"6x\"] .habit{padding:var(--py) var(--px);border:1px solid var(--line);border-radius:12px;background:var(--panel-paper);align-items:center;grid-template-areas:\"hd cells\";row-gap:3px}\n.card[data-size^=\"6x\"] .hd{flex-direction:column;align-items:flex-start;justify-content:center;gap:1px}\n.card[data-size^=\"6x\"] .hname{width:100%;flex:none;font-size:13px}\n.card[data-size^=\"6x\"] .cell{aspect-ratio:auto}\n.card[data-size^=\"6x\"] .fields{display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:start}\n\n/* 6x3 */\n.card[data-size=\"6x3\"] .pg{padding:8px 12px;gap:5px}\n.card[data-size=\"6x3\"] .ttl{flex-direction:row;align-items:baseline;gap:8px}\n.card[data-size=\"6x3\"] .list{gap:4px}\n.card[data-size=\"6x3\"] .cell{height:28px}\n\n/* 6x6 */\n.card[data-size=\"6x6\"] .pg{padding:16px;gap:8px;--hw:128px;--py:8px;--px:10px}\n.card[data-size=\"6x6\"] .name{font-size:18px}\n.card[data-size=\"6x6\"] .range{font-size:12px}\n.card[data-size=\"6x6\"] .ib{width:32px;height:32px;font-size:18px}\n.card[data-size=\"6x6\"] .sum{display:flex;font-size:13px}\n.card[data-size=\"6x6\"] .hint{display:block;font-size:12px}\n.card[data-size=\"6x6\"] .habit{grid-template-areas:\"hd cells\" \"meta cells\"}\n.card[data-size=\"6x6\"] .meta{display:flex;flex-direction:column;gap:3px;align-self:start}\n.card[data-size=\"6x6\"] .wd .dt{display:block}\n.card[data-size=\"6x6\"] .wd{font-size:11px}\n.card[data-size=\"6x6\"] .cell{height:36px;font-size:15px}\n.card[data-size=\"6x6\"] .hname{font-size:14px}\n.card[data-size=\"6x6\"] .nm{white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow-wrap:anywhere}\n.card[data-size=\"6x6\"] .inp{height:38px;font-size:15px}\n.card[data-size=\"6x6\"] .sgb{height:36px;font-size:14px}\n.card[data-size=\"6x6\"] .btn{height:38px;font-size:14px}\n.card[data-size=\"6x6\"] .note{font-size:12px}\n.card[data-size=\"6x6\"] .lb{font-size:12px}\n";
function initialize(s){
  const base=s&&typeof s==='object'?s:{};
  if(Array.isArray(base.habits))return s;
  return {
    ...base,
    habits:[
      {id:'h-sleep',name:'早睡',target:5},
      {id:'h-stretch',name:'拉伸',target:3},
      {id:'h-read',name:'阅读',target:4}
    ],
    checks:base.checks&&typeof base.checks==='object'?base.checks:{}
  };
}
function pd(str){const p=String(str).split('-');return new Date(Number(p[0]),Number(p[1])-1,Number(p[2]));}
function fd(dt){const m=dt.getMonth()+1,d=dt.getDate();return dt.getFullYear()+'-'+(m<10?'0':'')+m+'-'+(d<10?'0':'')+d;}
function addDays(str,n){const dt=pd(str);dt.setDate(dt.getDate()+n);return fd(dt);}
function wdChar(str){return '日一二三四五六'.charAt(pd(str).getDay());}
function mdText(str){const p=String(str).split('-');return Number(p[1])+'/'+Number(p[2]);}
function dayNum(str){return String(Number(String(str).split('-')[2]));}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const habits=Array.isArray(state.habits)?state.habits:[];
  const checks=state.checks&&typeof state.checks==='object'?state.checks:{};
  const today=day();
  const shift=Math.max(0,Number(ui.shift)||0);
  const end=addDays(today,-shift);
  const days=[];
  for(let i=6;i>=0;i--)days.push(addDays(end,-i));
  let listEl=null;

  function E(tag,attrs,...kids){
    const flat=[];
    kids.forEach(k=>{
      (Array.isArray(k)?k:[k]).forEach(x=>{
        if(x!==null&&x!==undefined&&x!==false)flat.push(typeof x==='number'?String(x):x);
      });
    });
    return el(tag,attrs||{},...flat);
  }
  function isDone(id,d){const m=checks[id];return !!(m&&m[d]);}
  function countIn(id){let n=0;days.forEach(d=>{if(isDone(id,d))n+=1;});return n;}
  function totalOf(id){const m=checks[id];if(!m)return 0;return Object.keys(m).filter(k=>m[k]).length;}
  function goto(patch){Object.assign(ui,patch);redraw();}
  function fail(msg){ui.err=msg;ui.busy=false;redraw();}
  function backToList(){goto({mode:'list',draft:null,editId:null,err:'',confirmDel:false,busy:false});}
  function nextUi(extra){
    return {shift:shift,mode:'list',scroll:ui.scroll||0,busy:false,err:'',confirmDel:false,draft:null,editId:null,...extra};
  }

  function toggle(id,d){
    update(s=>{
      const all={...(s.checks||{})};
      const m={...(all[id]||{})};
      if(m[d])delete m[d];else m[d]=true;
      all[id]=m;
      return {...s,checks:all};
    }).catch(()=>fail('保存失败，请再点一次'));
  }
  function openEdit(h){
    goto({mode:'edit',editId:h?h.id:null,draft:{name:h?h.name:'',target:h?(Number(h.target)||1):5},err:'',confirmDel:false,busy:false});
  }

  function saveDraft(){
    if(ui.busy)return;
    const d=ui.draft||{};
    const name=String(d.name||'').trim();
    const target=Number(d.target);
    if(!name){ui.err='请先填写习惯名称';redraw();return;}
    if(name.length>16){ui.err='名称最多 16 个字';redraw();return;}
    if(!(Number.isInteger(target)&&target>=1&&target<=7)){ui.err='每周目标请选择 1–7 次';redraw();return;}
    const isNew=!ui.editId;
    const id=ui.editId||uid();
    ui.busy=true;
    ui.err='';
    commit(s=>{
      const list=Array.isArray(s.habits)?s.habits:[];
      const next=isNew?[...list,{id:id,name:name,target:target}]:list.map(x=>x.id===id?{...x,name:name,target:target}:x);
      return {...s,habits:next};
    },nextUi({scroll:isNew?99999:(ui.scroll||0)})).catch(()=>fail('保存失败，请重试'));
  }
  function doDelete(){
    if(ui.busy)return;
    const id=ui.editId;
    ui.busy=true;
    commit(s=>{
      const all={...(s.checks||{})};
      delete all[id];
      return {...s,habits:(Array.isArray(s.habits)?s.habits:[]).filter(x=>x.id!==id),checks:all};
    },nextUi({})).catch(()=>fail('删除失败，请重试'));
  }


  function cellBtn(h,d){
    const done=isDone(h.id,d);
    const isToday=d===today;
    const label=h.name+'，'+mdText(d)+(isToday?'（今天）':'')+'，'+(done?'已完成，点按取消':(isToday?'未打卡，点按打卡':'未打卡，点按补记'));
    return E('button',{class:'cell'+(done?' on':'')+(isToday?' today':''),type:'button','aria-pressed':done?'true':'false','aria-label':label,onclick:()=>toggle(h.id,d)},done?'✓':null);
  }

  function habitRow(h){
    const t=Math.min(7,Math.max(1,Number(h.target)||1));
    const n=countIn(h.id);
    const met=n>=t;
    const ticks=[];
    for(let i=0;i<t;i++)ticks.push(E('span',{class:'tick'+(i<n?' f':'')}));
    return E('div',{class:'habit'+(met?' met':'')},
      E('div',{class:'hd'},
        E('button',{class:'hname',type:'button','aria-label':'编辑习惯：'+h.name+'，每周目标 '+t+' 次',onclick:()=>openEdit(h)},
          E('span',{class:'nm'},h.name),
          E('span',{class:'pen','aria-hidden':'true'},'✎')),
        E('div',{class:'stat','aria-label':'完成 '+n+' 次，目标 '+t+' 次'},
          E('span',{class:'n'},n+'/'+t),
          met?E('span',{class:'ok'},'✓ 达标'):null)),
      E('div',{class:'cells'},days.map(d=>cellBtn(h,d))),
      E('div',{class:'meta'},
        E('div',{class:'ticks','aria-hidden':'true'},ticks),
        E('div',{class:'tot'},'累计 '+totalOf(h.id)+' 次')));
  }

  function renderList(){
    let sumN=0,metN=0;
    habits.forEach(h=>{
      const n=countIn(h.id);
      sumN+=n;
      if(n>=(Number(h.target)||1))metN+=1;
    });
    const prev=E('button',{class:'ib',type:'button','aria-label':'查看更早的 7 天',onclick:()=>goto({shift:shift+7,err:''})},'‹');
    const next=E('button',{class:'ib',type:'button','aria-label':'查看更近的 7 天',disabled:shift===0,onclick:()=>goto({shift:Math.max(0,shift-7),err:''})},'›');
    const add=E('button',{class:'ib add',type:'button','aria-label':'新增习惯',onclick:()=>openEdit(null)},'+');
    const head=E('div',{class:'bar'},
      E('div',{class:'ttl'},
        E('span',{class:'name'},'习惯打卡'),
        E('span',{class:'range '+(shift===0?'now':'past')},
          E('span',{class:'rg-a'},shift===0?'近7天':'往期'),
          E('span',{class:'rg-b'},mdText(days[0])+' – '+mdText(days[6])))),
      E('div',{class:'ctl'},prev,next,add));
    const sum=E('div',{class:'sum'},
      E('span',null,(shift===0?'近7天':'该周')+'完成 '+sumN+' 次'),
      E('span',{class:'dot','aria-hidden':'true'},'·'),
      E('span',null,'达标 '+metN+'/'+habits.length+' 个习惯'));
    const wk=E('div',{class:'wk'},
      E('div',{class:'wk-sp'}),
      E('div',{class:'wds'},days.map(d=>E('div',{class:'wd'+(d===today?' today':'')},
        E('span',{class:'w'},wdChar(d)),
        E('span',{class:'dt'},dayNum(d))))));
    const rows=habits.length?habits.map(habitRow):[E('div',{class:'empty'},'还没有习惯，点右上角“+”添加。')];
    listEl=E('div',{class:'list'},habits.length?wk:null,rows);
    listEl.onscroll=()=>{ui.scroll=listEl.scrollTop;};
    const hint=E('div',{class:'hint'},'点任意一天即可补记，再点一次取消。漏打一天，之前的记录都会保留。');
    const err=ui.err?E('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;
    return E('div',{class:'pg'},head,sum,err,listEl,hint);
  }


  function renderEdit(){
    const h=ui.editId?habits.find(x=>x.id===ui.editId):null;
    const isNew=!ui.editId;
    if(!ui.draft)ui.draft={name:'',target:5};
    const d=ui.draft;
    const nameInput=E('input',{class:'inp',value:d.name||'',placeholder:'习惯名称，如：喝水','aria-label':'习惯名称',maxlength:16,
      oninput:e=>{d.name=e.target.value;},
      onkeydown:e=>{if(e.key==='Enter')saveDraft();}});
    const segs=[];
    for(let k=1;k<=7;k++){
      const sel=Number(d.target)===k;
      segs.push(E('button',{class:'sgb'+(sel?' sel':''),type:'button','aria-pressed':sel?'true':'false','aria-label':'每周 '+k+' 次',onclick:()=>{d.target=k;redraw();}},String(k)));
    }
    const fields=E('div',{class:'fields'},
      E('label',{class:'fld'},E('span',{class:'lb'},'习惯名称'),nameInput),
      E('div',{class:'fld'},
        E('span',{class:'lb'},'每周目标：'+Number(d.target)+' 次'),
        E('div',{class:'segs',role:'group','aria-label':'每周目标次数'},segs)));
    const note=isNew?'每天最多打卡一次，所以每周目标最多 7 次。':'已累计 '+totalOf(h?h.id:'')+' 次记录；改名或改目标不会影响已有记录。';
    let actions;
    if(ui.confirmDel&&h){
      actions=E('div',{class:'confirm'},
        E('div',{class:'cmsg'},'删除后会同时清除「'+h.name+'」的全部 '+totalOf(h.id)+' 次记录，无法恢复。'),
        E('div',{class:'row'},
          E('button',{class:'btn primary',type:'button',disabled:!!ui.busy,onclick:doDelete},ui.busy?'删除中…':'确认删除'),
          E('button',{class:'btn',type:'button',onclick:()=>goto({confirmDel:false})},'不删了')));
    }else{
      actions=E('div',{class:'row'},
        E('button',{class:'btn primary',type:'button',disabled:!!ui.busy,onclick:saveDraft},ui.busy?'保存中…':'保存'),
        E('button',{class:'btn',type:'button',onclick:backToList},'取消'),
        isNew?null:E('button',{class:'btn ghost',type:'button',onclick:()=>goto({confirmDel:true,err:''})},'删除'));
    }
    return E('div',{class:'pg edit'},
      E('div',{class:'bar'},
        E('button',{class:'back',type:'button','aria-label':'返回',onclick:backToList},'‹ 返回'),
        E('span',{class:'etitle'},isNew?'新增习惯':'编辑习惯')),
      E('div',{class:'ebody'},
        fields,
        E('div',{class:'note'},note),
        ui.err?E('div',{class:'err',role:'alert'},'⚠ '+ui.err):null),
      actions);
  }

  if(ui.mode==='edit'&&ui.editId&&!habits.some(x=>x.id===ui.editId))ui.mode='list';
  root.append(ui.mode==='edit'?renderEdit():renderList());
